import { Component, HostListener, signal, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { LanguageSwitcherComponent } from '../language-switcher/language-switcher.component';

interface NavLink {
  label: string;
  i18nKey: string;
  href: string;
}

@Component({
  selector: 'app-header',
  standalone: true,
  imports: [CommonModule, RouterLink, TranslateModule, LanguageSwitcherComponent],
  templateUrl: './header.component.html',
  styleUrl: './header.component.scss',
})
export class HeaderComponent implements OnInit {
  isScrolled = signal(false);
  menuOpen = signal(false);
  isDarkTheme = signal(this.getTheme() === 'dark');

  navLinks: NavLink[] = [
    { label: '', i18nKey: 'header.biografia', href: '#biografia' },
    { label: '', i18nKey: 'header.lezha', href: '#lezha' },
    { label: '', i18nKey: 'header.galleria', href: '#galleria' },
    { label: '', i18nKey: 'header.pubblicazioni', href: '#pubblicazioni' },
    { label: '', i18nKey: 'header.video', href: '#video' },
    { label: '', i18nKey: 'header.contatti', href: '#contatti' },
  ];

  constructor(private translate: TranslateService) {}

  ngOnInit(): void {
    this.updateNavLabels();
    this.translate.onLangChange.subscribe(() => {
      this.updateNavLabels();
    });
  }

  private updateNavLabels(): void {
    this.navLinks.forEach((link) => {
      this.translate.get(link.i18nKey).subscribe((text: string) => {
        link.label = text;
      });
    });
  }

  @HostListener('window:scroll', [])
  onScroll() {
    this.isScrolled.set(window.scrollY > 50);
  }

  toggleTheme() {
    const newTheme = this.isDarkTheme() ? 'light' : 'dark';
    document.documentElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('theme', newTheme);
    this.isDarkTheme.set(newTheme === 'dark');
  }

  toggleMenu() {
    this.menuOpen.set(!this.menuOpen());
  }

  closeMenu() {
    this.menuOpen.set(false);
  }

  isAdmin(): boolean {
    return !!localStorage.getItem('auth_token');
  }

  private getTheme(): string {
    return localStorage.getItem('theme') || 'dark';
  }
}
<header class="header" [class.scrolled]="isScrolled()">
  <div class="header-container">
    <a href="#" class="logo">
      <span class="logo-circle">P·Z</span>
      <span class="logo-text">Pualin Zefi</span>
    </a>

    <nav class="nav-desktop">
      <a *ngFor="let link of navLinks" [href]="link.href" (click)="closeMenu()">
        {{ link.label }}
      </a>
      <a *ngIf="!isAdmin()" href="/login" class="login-link">
        <i class="fa-solid fa-sign-in-alt"></i> {{ 'common.login' | translate }}
      </a>
      <a *ngIf="isAdmin()" href="/admin" class="admin-link">
        <i class="fa-solid fa-cog"></i> {{ 'admin.profile' | translate }}
      </a>
    </nav>

    <div class="header-actions">
      <app-language-switcher></app-language-switcher>

      <button class="theme-toggle" (click)="toggleTheme()" [attr.aria-label]="isDarkTheme() ? 'Light theme' : 'Dark theme'">
        <i [ngClass]="isDarkTheme() ? 'fa-solid fa-sun' : 'fa-solid fa-moon'"></i>
      </button>

      <button class="menu-toggle" (click)="toggleMenu()" [class.active]="menuOpen()">
        <span></span>
        <span></span>
        <span></span>
      </button>
    </div>
  </div>

  <nav class="nav-mobile" [class.open]="menuOpen()">
    <a *ngFor="let link of navLinks" [href]="link.href" (click)="closeMenu()">
      {{ link.label }}
    </a>
    <a *ngIf="!isAdmin()" href="/login" (click)="closeMenu()">
      <i class="fa-solid fa-sign-in-alt"></i> {{ 'common.login' | translate }}
    </a>
    <a *ngIf="isAdmin()" href="/admin" (click)="closeMenu()">
      <i class="fa-solid fa-cog"></i> {{ 'admin.profile' | translate }}
    </a>
    <div class="mobile-language-switcher">
      <app-language-switcher></app-language-switcher>
    </div>
  </nav>
</header>
